NewHeadOffset := 0;
ToNewHeadOffset := true;

if (abs(HeadOffset) > 5)
    Scan.Departing();
return [];

Arriving.Z:
NewHeadOffset := HeadOffsetStart;
ToNewHeadOffset:=false;
SampleZ := 0.0;
AwaitDrift := true;
if (RegulatorZ.MaximalPossibleSetpoint * RegulatorZ.RelativeSetpoint < abs(AveragedMechanical[1]))
    Scan.Arriving();
return [];

WaitingForward.RowColumnDepth:
ToNewHeadOffset := false;
if (PixelDepth == Scan.Rows)
    Scan.MovingBackward();
else
    Scan.MovingForward();
return [];

MovingForward.Z:
ToNewHeadOffset := true;
if (AwaitDrift) {
    driftIterator := driftIterator + 1;
    if (driftIterator%1250 == 0){
        PreviousZ := CurrentZ;
        CurrentZ := AveragedZ;
    }
    if (abs(CurrentZ - PreviousZ) < 0.05*0.001 and PreviousZ > 0)
        AwaitDrift := false;
    Scan.MovingForward();
    //SampleZ := (140-UnaveragedZ)*SampleZScaling;
    SampleZ := UnaveragedZ;
    return [];
}
else {
    NewHeadOffset := HeadOffsetStart - (PixelDepth/(Scan.Rows-1) * Scan.Size.Z) / (0.001*HeadZScaling);
    if (NewHeadOffset < -10000)
        Scan.MovingBackward();
    else if (abs(HeadOffset-NewHeadOffset) < OffsetTolerance)
        Scan.WaitingForward();
    else
        Scan.MovingForward();
    return [SampleZ];
}

MovingBackward.Z:
NewHeadOffset := HeadOffset+1; //5 is effective approach speed and to be determined
ToNewHeadOffset := true;
//if ((abs(HeadOffset - NewHeadOffset) < OffsetTolerance)){ //end of scan or drift into contact
//    return [];
//}
if (RegulatorZ.MaximalPossibleSetpoint * RegulatorZ.RelativeSetpoint > abs(AveragedMechanical[1]))
    Scan.End();
return [SampleZ];

Outputs.Mechanical:
var v[6];

for (var n := 0; n < 6; n+=1){
    switch {
        case n == 5:
            v[n] := [(HeadOffsetStart-HeadOffset)*HeadZScaling];
        default:
            v[n] := AveragedMechanical[n];
    }
}
if (PreviousZ >= 0)    
    v[4] := (CurrentZ - PreviousZ)*1000;
return [v];
